// Antwort des Cockpits mit dem gemeldeten Lauf zusammenführen — kurz und ohne Dokumentinhalte.
const meldung = $('Lauf-Ende von Modul 01 (Header-Auth)').first().json.body ?? {};
const antwort = $input.first().json ?? {};
return [{ json: {
  ok: antwort.ok === true,
  lauf: meldung.lauf ?? null,
  objekt: meldung.objekt ?? null,
  laufStatus: meldung.status ?? null,
  angelegt: Array.isArray(antwort.angelegt) ? antwort.angelegt : [],
  uebersprungen: Array.isArray(antwort.uebersprungen) ? antwort.uebersprungen : [],
  abgleiche: antwort.abgleiche ?? null,
  cockpitFehler: antwort.ok === true ? null : (antwort.grund ?? antwort.fehler ?? 'Cockpit hat nicht mit ok geantwortet'),
} }];
